/**
 * Cyber Health report content — the static, hand-authored library behind
 * the PDF report and lead/CRM payloads generated by
 * app/api/cyber-health/route.ts.
 *
 * Design decision (explicit, approved): this content is a FIXED library,
 * not a live LLM call. The original Tally/n8n/HubSpot pipeline appears to
 * have generated this wording with an AI step per submission — this
 * version authors one canonical, on-brand entry per question instead.
 * Reasons: no new API key/cost per report, no latency, no risk of an AI
 * inventing an inaccurate security claim under the ORAGROL brand, and the
 * output is fully predictable/reviewable ahead of time — the standard a
 * real MSSP report is held to. The "AI-Assisted Assessment" framing still
 * holds honestly: the assessment adapts in real time to the person's
 * actual answers (filtering, weighting, category grouping, roadmap
 * sequencing), it just doesn't generate prose live.
 */
import { categories, questions } from "./assessment-data";

export type Severity = "Critical" | "High" | "Medium" | "Low";
export type Answer = "Yes" | "No" | "Not Sure";

export interface Finding {
  id: string; // question id, e.g. "Q05-1"
  title: string;
  severity: Severity;
  businessImpact: string;
  likelihood: string;
  action: string;
  effort: "Low" | "Medium" | "High";
  timeRequired: string;
}

