// Sanity check at module load, dev-time only: every question in
// assessment-data.ts must have a matching finding entry.
if (process.env.NODE_ENV !== "production") {
  const missing = questions.map((q) => q.id).filter((id) => !FINDINGS[id]);
  if (missing.length) {
    console.warn(`[cyber-health/report-data] Missing FINDINGS entries for: ${missing.join(", ")}`);
  }
}

// The 5 executive-report groupings, mapped onto the 20 existing scoring
