export const CATEGORY_GROUPS: { name: string; categoryIds: string[] }[] = [
  { name: "Identity Security", categoryIds: ["01", "02", "10"] },
  { name: "Infrastructure", categoryIds: ["03", "04", "05", "07", "11", "12", "15"] },
  { name: "Cloud & Data", categoryIds: ["06", "08", "13", "16"] },
  { name: "Governance", categoryIds: ["09", "14", "19"] },
  { name: "Business Resilience", categoryIds: ["17", "18", "20"] },
];

export function categoryIdsForGroup(name: string): string[] {
  return CATEGORY_GROUPS.find((g) => g.name === name)?.categoryIds ?? [];
}

// A curated 5-item "at a glance" strip — one representative category per
// pillar, not the same list as CATEGORY_GROUPS above.
