export function groupDescription(pct: number): string {
  if (pct >= 90) return "a genuine strength — a solid foundation the rest of the business can rely on.";
  if (pct >= 60) return "broadly sound, with a few specific gaps worth closing.";
  if (pct >= 40) return "showing real gaps that should be prioritized soon.";
  return "a significant risk area that needs attention first.";
}

export function maturityLabel(score: number): string {
  if (score >= 80) return "Strong";
  if (score >= 60) return "Needs Improvement";
  if (score >= 40) return "At Risk";
  return "Critical";
}

export function riskTier(score: number): "Low" | "Medium" | "High" | "Critical" {
  return score >= 80 ? "Low" : score >= 60 ? "Medium" : score >= 40 ? "High" : "Critical";
}

export type PackageTier = "Starter" | "Standard" | "Premium";

export function recommendedPackage(score: number): PackageTier {
  return score >= 80 ? "Starter" : score >= 60 ? "Standard" : "Premium";
}

