export function generateClientReference(): string {
  const year = new Date().getFullYear();
  const n = Math.floor(100000 + Math.random() * 900000);
  return `OCR-${year}-${n}`;
}

export function generateReportId(): string {
  const year = new Date().getFullYear();
  const n = Math.floor(100000 + Math.random() * 900000);
  return `ORG-${year}-${n}`;
}

